    var localOpenAdmin=openAdmin;openAdmin=function(){if(!state.configured)return localOpenAdmin();if(!state.user)return requireAuth(openAdmin);if(state.user.role!=='admin')return toast('This account does not have administrator access',true);api('/api/admin/overview').then(function(data){adminDemo=loadAdmin();adminDemo.users=(data.users||[]).map(function(u){return {id:u.id,name:u.display_name||u.username,email:'@'+u.username,role:u.role==='user'?'member':u.role,status:u.status,joined:new Date(u.joined_at).toLocaleDateString('en-US')}});if(data.settings&&data.settings[0])adminDemo.settings=Object.assign(adminDemo.settings,data.settings[0].value||{});if(data.tags&&data.tags.length)tags=data.tags;if(data.reports)adminDemo.reports=data.reports.map(function(r){return {id:r.id,type:r.reason,content:r.details||'Reported content',user:'member',time:new Date(r.created_at).toLocaleString('en-US'),status:r.status}});localOpenAdmin()}).catch(function(e){toast(e.message,true)})};
